import {trainingStretcher} from './station-exercises.js';
import {exercisePose,footballPoint} from './station-exercises.js';
import {batchStatic} from './batching.js';
import {applyPersonInsignia} from './crew-insignia.js';
import {stationSpaces} from './station-spaces.js';
import * as T from 'three';import {person,captain,dressCaptain,dressMedicalResponder,dressDepartureResponder,box,sign,cylinder} from './models.js';import {crewPosition,duty,boardingPosition,inspectionPosition} from './crew.js';
export function stationLife(world){const group=new T.Group();world.add(group);box(group,44,.2,42,'#a9afa5',-70,.2,34);for(const [w,d,x,z]of[[44,.45,-70,12],[44,.45,-70,56],[.45,44,-92,34],[.45,44,-48,34]])box(group,w,3.8,d,'#bac7bf',x,2.1,z);const roof=box(group,45,.18,43,new T.MeshStandardMaterial({color:'#71807c'}),-70,4.08,34);roof.castShadow=true;sign(group,'DORTOIR',12,1,-70,3.2,12.25);for(let i=0;i<24;i++){const x=-87+(i%6)*6,z=18+Math.floor(i/6)*6;for(const level of[0,1]){const y=.72+level*1.55;for(const sx of[-.78,.78])box(group,.1,level?.15:.55,.1,'#53615f',x+sx,y-.25,z);box(group,1.8,.16,2.9,'#718886',x,y,z);box(group,1.65,.16,2.72,'#b7c4b5',x,y+.15,z);box(group,1.45,.16,.55,'#e6e7d9',x,y+.28,z-1);}}box(group,4,.08,.9,'#6c7974',-70,.25,55.7);for(const [label,x]of[['SPORT',-85],['REPAS',-70],['RANGEMENT',-54]])sign(group,label,10,.7,x,1,53);for(let i=0;i<3;i++){box(group,8,.15,1.7,'#98754d',-69,1.05,42+i*3);box(group,8,.4,.4,'#60716a',-69,.6,43+i*3);box(group,1.3,2.5,1,'#6b7978',-54+i*2,1.5,43);}sign(group,'VSAV • ZONE HYGIÈNE',12,.7,-56,3,55.8,'#447d7e');sign(group,'ENGINS INCENDIE & APPUI',13,.7,-84,3,55.8,'#964539');const ball=new T.Mesh(new T.SphereGeometry(.32,10,8),new T.MeshStandardMaterial({color:'#e9e8d9'}));group.add(ball);
const practice=new T.Group();group.add(practice);for(const x of[-80,-62]){cylinder(practice,0,.35,.8,'#e99034',x,.55,84,8);box(practice,1,.08,1,'#334144',x,.15,84);}for(let i=0;i<18;i++)box(practice,.1,.07,.6,'#cdbd8a',-83+Math.sin(i*.25)*.2,.17,73+i*.56);const trainingBed=new T.Group();trainingBed.name='Brancard de manœuvre';practice.add(trainingBed);box(trainingBed,.75,.12,2.1,'#b9a56d',0,.78,0);for(const z of[-1.18,1.18])box(trainingBed,.65,.05,.05,'#a5b7b5',0,.8,z);for(const x of[-.28,.28])for(const z of[-.75,.75])box(trainingBed,.04,.7,.04,'#758e8c',x,.38,z);box(practice,.44,.2,1.6,'#c99a80',-71,.32,79);box(practice,.9,.1,2,'#5a857e',-71,.12,79);cylinder(practice,.3,.3,.18,'#6b7273',-81,.3,73,12);sign(practice,'MANŒUVRES',8,.6,-78,1.3,87);
stationSpaces(group);batchStatic(group,[roof,ball,practice]);const models=new Map();return{setInterior(open){roof.visible=!open;},update(t,s,engines){updateMorningChecks(s,engines);const sporting=s.roster.some(p=>p.present&&!p.engine&&!p.atResidence&&!p.role)&&s.minute%1440>=640&&s.minute%1440<680;ball.visible=sporting;const ballAt=footballPoint(s.minute%1440);ball.position.set(ballAt[0],.48,ballAt[1]);practice.visible=duty(s.minute)==='training';const trainingPose=trainingStretcher(s.minute);trainingBed.position.set(trainingPose.point[0],0,trainingPose.point[1]);trainingBed.rotation.y=trainingPose.yaw;for(const m of models.values())m.visible=false;for(const p of s.roster){if(!models.has(p.id))models.set(p.id,p.role==='captain'?captain(group,0,0,s.playerProfile):person(group,0,0,p.kind==='SPV'?'#74613c':'#334b65'));const m=models.get(p.id),e=engines.find(e=>e.id===p.engine);const b=e?.boarding?.find(b=>b.id===p.id),equipped=!!(e?.call!=null&&b&&s.minute-e.alertAt>=b.delay);if(p.role==='captain')dressCaptain(m,equipped&&s.playerProfile.outfit==='station'?{...s.playerProfile,outfit:'fire'}:s.playerProfile);else dressDepartureResponder(m,e,equipped);m.visible=p.present&&!p.atResidence&&(!e||e.status==='departing'&&e.wasAtStation);if(!m.visible)continue;applyPersonInsignia(m,p,s.playerProfile);const task=duty(s.minute);m.rotation.set(0,0,0);m.scale.setScalar(1);let pos=crewPosition(p,s.minute,engines),y=.3;const inspection=!e&&inspectionPosition(p,s.minute,engines);if(inspection){const {engine,phase}=inspection;y+=phase>.7&&phase<.88?.7:0;m.children[3].rotation.x=-.65;m.rotation.y=engine.model.rotation.y;}else m.children[3].rotation.x=0;if(e){const b=e.boarding?.find(b=>b.id===p.id);if(b){const elapsed=s.minute-e.alertAt;m.visible=elapsed<b.duration;const fraction=Math.max(0,Math.min(1,(elapsed-b.delay)/(b.duration-b.delay)));const at=boardingPosition(b,fraction);pos=at.point;m.rotation.y=at.yaw;}}else if(task==='dormitory'){m.rotation.x=-Math.PI/2;y=(p.slot??p.id)>=24?2.67:1.12;}else if(!['meal','breakfast','rest','briefing','equipment','sport','training'].includes(task)){pos=[pos[0]+Math.sin(t*.6+p.id)*.6,pos[1]+Math.cos(t*.6+p.id)*.6];y+=task==='sport'?Math.abs(Math.sin(t*3+p.id))*.15:0;}if(!e&&m.userData.lastDuty&&m.userData.lastDuty!==task&&task!=='dormitory')m.userData.roomWalk={from:[m.position.x,m.position.z],at:s.minute};
m.userData.lastDuty=task;const crossing=m.userData.roomWalk;if(crossing&&!e){const dist=Math.hypot(pos[0]-crossing.from[0],pos[1]-crossing.from[1]),f=Math.min(1,(s.minute-crossing.at)/Math.max(1,dist/14));pos=[crossing.from[0]+(pos[0]-crossing.from[0])*f,crossing.from[1]+(pos[1]-crossing.from[1])*f];m.rotation.y=Math.atan2(pos[0]-m.position.x,pos[1]-m.position.z);if(f>=1)delete m.userData.roomWalk;}if(e)delete m.userData.roomWalk;m.position.set(pos[0],y,pos[1]);const moving=e||['sport','training','equipment'].includes(task);m.children[1].rotation.x=moving?Math.sin(t*5+p.id)*.3:0;m.children[2].rotation.x=moving?-Math.sin(t*5+p.id)*.3:0;if(!e&&!inspection&&!m.userData.roomWalk&&['sport','training'].includes(task)){const clock=s.minute%1440,slot=p.slot??p.id,outing=task==='sport'&&clock>=600&&clock<720&&!p.role;if(outing){const next=crewPosition(p,s.minute+.03,engines);m.rotation.y=Math.atan2(next[0]-pos[0],next[1]-pos[1]);m.children[1].rotation.x=Math.sin(s.minute*15+slot)*.6;m.children[2].rotation.x=-m.children[1].rotation.x;m.children[3].rotation.x=-m.children[1].rotation.x;m.children[4].rotation.x=m.children[1].rotation.x;}else if(!p.role){const pose=exercisePose(slot,s.minute,task==='sport');m.rotation.set(pose.body,pose.yaw,0);m.children[1].rotation.x=pose.leg;m.children[2].rotation.x=-pose.leg;m.children[3].rotation.x=pose.arm;m.children[4].rotation.x=task==='sport'?-pose.arm:pose.arm;m.userData.exercise=pose.label;}}}}};}

// One staggered inspection per morning, cancelled as soon as a unit is engaged.
export function updateMorningChecks(state,engines){
 const minute=((state.minute%1440)+1440)%1440;
 engines.forEach((e,i)=>{const data=e.model.userData,age=minute-(525+i*1.6),active=e.status==='ready'&&!e.external&&!e.atResidence&&age>=0&&age<12;
 data.routineTesting=active&&age>=2&&age<5;
 data.routineHeadlights=active&&age>=1&&age<6;
 data.routineAmber=active&&age>=3&&age<5;
 // EPA : sort sur l'aire (4-5 min), essaie l'échelle dehors, puis rentre (11-12 min).
 data.routineOut=active&&e.kind==='EPA'?Math.max(0,Math.min(1,age-4,12-age)):0;
 data.routineLadder=active&&e.kind==='EPA'?Math.max(0,Math.min(1,(age-5)/2,(11-age)/2)):0;
 data.routineCheck=active?(age<2?'Tour de l’engin':age<5?'Essai éclairage et signalisation':age<11&&e.kind==='EPA'?'Essai stabilisateurs et échelle':'Contrôle du matériel et rangement'):null;
 });
}
